class Cache:
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock

    def _expiry(self, key):
        expiry = self.clock.now().add(seconds=self.ttl) if self.ttl is not None else None
        return expiry

    def set(self, key, value):
        self[key] = value
        self._expiry(key) = self._expiry(key)  # refresh expiry on overwrite

    def get(self, key, default=None):
        expiry = self._expiry(key)
        if expiry is not None:
            value = self[key]
            if value is not None and self._expiry(key) >= expiry:
                value = value
            return value
        return default

